html:
{% set c = shatam_certificate_context(doc) %}
<style>
@page { size: A4 landscape; margin: 0; }
html, body { margin: 0; padding: 0; }
.print-format { margin-top: 0; margin-right: 0; margin-bottom: 0; margin-left: 0; padding: 0; }
.sc-page { position: relative; width: 297mm; height: 209mm; overflow: hidden; page-break-after: avoid; page-break-inside: avoid; font-family: Georgia, 'Times New Roman', serif; color: #14532d; }
.sc-bg { position: absolute; left: 0; top: 0; width: 297mm; height: 209mm; }
.sc-fallback { position: absolute; left: 8mm; top: 8mm; width: 279mm; height: 193mm; border: 2mm solid #14532d; }
.sc-fallback-name { position: absolute; left: 0; top: 18mm; width: 100%; text-align: center; font-size: 28pt; font-weight: bold; letter-spacing: 2pt; text-transform: uppercase; }
.sc-box { position: absolute; text-align: center; }
.sc-small { font-size: 12pt; color: #4b5563; }
.sc-label { font-size: 10pt; color: #6b7280; }
</style>
<div class="sc-page">
  {% if c.background %}
  <img class="sc-bg" src="{{ c.background }}">
  {% else %}
  <div class="sc-fallback"><div class="sc-fallback-name">{{ c.organisation | e }}</div></div>
  {% endif %}

  <div class="sc-box" style="left: 60mm; width: 177mm; top: 51mm;">
    <div style="font-size: 24pt; font-weight: bold; white-space: nowrap; line-height: 1.15;">{{ c.title | e }}</div>
    <div class="sc-small" style="margin-top: 1mm; white-space: nowrap;">This is to certify that</div>
  </div>

  <div class="sc-box" style="left: 59mm; width: 179mm; top: 77mm; font-size: {{ c.member_size }}pt; font-weight: bold; font-style: italic; line-height: 1.1; white-space: nowrap;">
    {{ c.member_name | e }}
  </div>

  <div class="sc-box" style="left: 59mm; width: 179mm; top: 104mm;">
    <div class="sc-small">has successfully completed</div>
    <div style="font-size: {{ c.course_size }}pt; font-weight: bold; margin-top: 1mm; white-space: nowrap;">{{ c.course_title | e }}</div>
  </div>

  <div class="sc-box" style="left: 41mm; width: 78mm; top: 138mm;">
    <div class="sc-label">Date of issue</div>
    <div style="font-size: 16pt; font-weight: bold;">{{ c.issue_date | e }}</div>
  </div>

  <div class="sc-box" style="left: 217mm; width: 36mm; top: 134mm;">
    {% if c.qr %}<img src="{{ c.qr }}" style="width: 24mm; height: 24mm;">{% endif %}
    <div style="font-size: 8pt; color: #4b5563; margin-top: 1mm;">{{ c.certificate_uid | e }}</div>
  </div>

  <div class="sc-box" style="left: 100mm; width: 97mm; top: 172mm;">
    <div style="font-size: 15pt; font-weight: bold;">{{ c.signatory_name | e }}</div>
    <div style="font-size: 11pt; color: #4b5563;">{{ c.signatory_title | e }}</div>
  </div>
</div>
